<h1 class="h3">Operaciones cerradas</h1><p class="text-muted">Ventas y alquileres registrados a partir de reservas aprobadas. Los vendedores ven las operaciones de sus reservas.</p>
<?php if (!$rows): ?><div class="card card-body text-center py-5"><h2 class="h5">Aún no hay cierres registrados</h2><a href="<?= BASE_URL ?>/reservations?estado=aprobada">Ver reservas aprobadas</a></div><?php else: ?>
<div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th scope="col">N.º</th><th>Fecha</th><th>Operación</th><th>Cliente / Inmueble</th><th>Vendedor</th><th>Monto final</th><th>Acciones</th></tr></thead><tbody><?php $rowNumber = 0; foreach ($rows as $item): ?><tr><th scope="row" class="text-muted text-center"><?= ++$rowNumber ?></th><td><?= e($item['fecha_cierre']) ?></td><td><?= e(Closing::TYPES[$item['tipo']]) ?></td><td><?= e($item['cliente']) ?><div class="small text-muted"><?= e($item['titulo']) ?></div></td><td><?= e($item['vendedor']) ?></td><td><?= e($item['moneda']) ?> <?= number_format((float)$item['monto_final'],0) ?><?= $item['tipo']==='alquiler' ? ' / mes' : '' ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/closings/show?id=<?= (int)$item['id'] ?>">Ver detalle</a></td></tr><?php endforeach; ?></tbody></table></div><p class="small text-muted mt-2">Hasta 100 cierres. Los montos de alquiler corresponden a la renta mensual pactada.</p><?php endif; ?>
